-- Lessons in stages: each Blockly lesson opens with a real problem, teaches two
-- short ideas, and checks understanding before (pre), during (mid) and at the
-- end (end, summative) of the lesson. Lessons unlock one after another.
--
-- 1. learning_quizzes.stage ties a quiz to a point in a lesson. Quizzes without a
--    stage keep working as before (level practice quizzes).
alter table public.learning_quizzes add column if not exists stage text
  check (stage is null or stage in ('pre', 'mid', 'end'));
alter table public.learning_quizzes drop constraint if exists learning_quizzes_stage_needs_lesson;
alter table public.learning_quizzes add constraint learning_quizzes_stage_needs_lesson
  check (stage is null or lesson_id is not null);
create index if not exists learning_quizzes_lesson_stage_idx on public.learning_quizzes(lesson_id, stage) where is_active;

create or replace function public.list_learning_quizzes() returns jsonb language sql stable security definer set search_path=public as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'slug',slug,'version',version,'title',title,'level',level,'lesson_id',lesson_id,'stage',stage,'pass_percent',pass_percent,'questions',questions) order by level,title),'[]'::jsonb)
 from public.learning_quizzes where is_active and exists(select 1 from public.profiles where id=auth.uid());
$$;

-- publish_learning_quiz gains an optional stage. The old seven-argument
-- version is dropped so PostgREST has one unambiguous signature.
drop function if exists public.publish_learning_quiz(text,text,text,uuid,integer,jsonb,jsonb);
drop function if exists public.publish_learning_quiz(text,text,text,uuid,integer,jsonb,jsonb,text);
create function public.publish_learning_quiz(p_slug text,p_title text,p_level text,p_lesson_id uuid,p_pass_percent integer,p_questions jsonb,p_solutions jsonb,p_stage text default null)
 returns uuid language plpgsql security definer set search_path=public as $$
declare q jsonb; s jsonb; v_id uuid; v_version integer;
begin
 if not public.me_is_admin() then raise exception 'Admin access required.' using errcode='42501'; end if;
 if p_slug is null or p_slug !~ '^[a-z0-9][a-z0-9-]{2,79}$' or length(btrim(coalesce(p_title,''))) not between 1 and 200
 or p_level is null or p_level not in ('beginner','intermediate','expert') or p_pass_percent is null or p_pass_percent not between 1 and 100
 or jsonb_typeof(p_questions) is distinct from 'array' or jsonb_typeof(p_solutions) is distinct from 'object' then raise exception 'Check the quiz title, level, questions and pass mark.'; end if;
 if p_stage is not null and p_stage not in ('pre','mid','end') then raise exception 'Choose before, during or end of the lesson.'; end if;
 if p_stage is not null and p_lesson_id is null then raise exception 'Choose the lesson this check belongs to.'; end if;
 if jsonb_array_length(p_questions) not between 1 and 30 then raise exception 'Use 1–30 questions.'; end if;
 if p_lesson_id is not null and not exists(select 1 from public.lessons where id=p_lesson_id and is_active) then raise exception 'Choose an active lesson.'; end if;
 if (select count(distinct value->>'id') from jsonb_array_elements(p_questions))<>jsonb_array_length(p_questions) then raise exception 'Question IDs must be distinct.'; end if;
 for q in select value from jsonb_array_elements(p_questions) loop
  s:=p_solutions->(q->>'id');
  if length(coalesce(q->>'id','')) not between 1 and 80 or length(btrim(coalesce(q->>'prompt',''))) not between 1 and 2000
   or jsonb_typeof(q->'choices') is distinct from 'array' then raise exception 'Each question needs a prompt and choices.'; end if;
  if jsonb_array_length(q->'choices') not between 2 and 6 or exists(select 1 from jsonb_array_elements(q->'choices') c where jsonb_typeof(c)<>'string' or length(btrim(c#>>'{}')) not between 1 and 1000)
   or s is null or jsonb_typeof(s->'correct') is distinct from 'number' or (s->>'correct') !~ '^[0-5]$'
   or (s->>'correct')::integer>=jsonb_array_length(q->'choices') or length(btrim(coalesce(s->>'explanation',''))) not between 1 and 2000 then raise exception 'Check choices, correct answer and explanation.'; end if;
 end loop;
 perform pg_advisory_xact_lock(hashtext(p_slug));
 select coalesce(max(version),0)+1 into v_version from public.learning_quizzes where slug=p_slug;
 update public.learning_quizzes set is_active=false where slug=p_slug;
 -- One active check per lesson stage: a newly published one replaces the old.
 if p_stage is not null then update public.learning_quizzes set is_active=false where lesson_id=p_lesson_id and stage=p_stage; end if;
 insert into public.learning_quizzes(slug,version,title,level,lesson_id,stage,pass_percent,questions,solutions)
 values(p_slug,v_version,btrim(p_title),p_level,p_lesson_id,p_stage,p_pass_percent,p_questions,p_solutions) returning id into v_id;
 return v_id;
end; $$;
revoke all on function public.publish_learning_quiz(text,text,text,uuid,integer,jsonb,jsonb,text) from public,anon;
grant execute on function public.publish_learning_quiz(text,text,text,uuid,integer,jsonb,jsonb,text) to authenticated;

-- 2. Lessons unlock in order. A learner may self-start a Blockly lesson when
--    it is the first lesson, when they have sent work for the lesson before it,
--    or when they already have it (started earlier or set by a teacher). A big
--    project opens once the last lesson of its level has been sent. Teachers
--    let a learner skip ahead by assigning the lesson to them.
create or replace function public.blockly_lesson_prerequisite(p_lesson_id uuid) returns uuid
language sql stable security definer set search_path=public as $$
 with target as (
  select id, kind, position, learning_plan->>'level' as level from public.lessons where id=p_lesson_id
 )
 select case when t.kind='project' then
   (select l.id from public.lessons l where l.is_active and l.kind='lesson' and l.learning_plan->>'delivery'='blockly'
     and l.learning_plan->>'level'=t.level order by l.position desc limit 1)
  else
   (select l.id from public.lessons l where l.is_active and l.kind='lesson' and l.learning_plan->>'delivery'='blockly'
     and l.position<t.position order by l.position desc limit 1)
  end
 from target t;
$$;
revoke all on function public.blockly_lesson_prerequisite(uuid) from public,anon;
grant execute on function public.blockly_lesson_prerequisite(uuid) to authenticated;

create or replace function public.start_blockly_lesson(p_lesson_id uuid)
 returns uuid language plpgsql security definer set search_path to 'public' as $function$
declare v_student uuid; v_school uuid; v_lesson public.lessons%rowtype; v_id uuid; v_before uuid;
begin
  select l.student_id,p.school_id into v_student,v_school from public.learner_accounts l
    join public.profiles p on p.id=l.profile_id where p.id=auth.uid() and public.is_my_learning_student(l.student_id);
  if not found then raise exception 'An active learner account is required.' using errcode='42501'; end if;
  select * into v_lesson from public.lessons where id=p_lesson_id and is_active
    and learning_plan->>'delivery'='blockly' and public.valid_lesson_learning_plan(learning_plan);
  if not found then raise exception 'This Blockly lesson is not available.' using errcode='22023'; end if;
  select a.id into v_id from public.learning_assignments a join public.learning_assignment_recipients r on r.assignment_id=a.id
    where a.lesson_id=p_lesson_id and a.school_id=v_school and r.student_id=v_student order by a.created_at desc limit 1;
  if found then return v_id; end if;
  v_before := public.blockly_lesson_prerequisite(p_lesson_id);
  if v_before is not null and not exists(
    select 1 from public.learning_submissions s join public.learning_assignments a on a.id=s.assignment_id
    where s.student_id=v_student and a.lesson_id=v_before) then
    raise exception 'Finish the lesson before this one first.' using errcode='22023';
  end if;
  insert into public.learning_assignments(school_id,lesson_id,title,instructions,learning_plan,assigned_by,self_started)
    values(v_school,v_lesson.id,v_lesson.title,'',v_lesson.learning_plan,auth.uid(),true)
    on conflict(lesson_id,school_id,assigned_by) where self_started do update set self_started=true returning id into v_id;
  insert into public.learning_assignment_recipients(assignment_id,student_id) values(v_id,v_student) on conflict do nothing;
  return v_id;
end;
$function$;

-- Self-started lessons used to carry a stock instruction full of jargon.
-- Teachers' own instructions are left alone.
update public.learning_assignments set instructions=''
 where self_started and instructions='Build, run and test this Blockly lesson. Submit your program and explanation for teacher review.';

-- 3. Stage content in very simple words. "problem" opens the lesson as a
--    real-life question, "ideas" are the two things to learn before building,
--    and titles, steps and expected results are rewritten for beginners: one
--    action per step and exactly what the screen should show. The teacher's
--    evidence brief and the skills each lesson covers are unchanged. This is reviewed
--    platform content, so the publication trigger is paused for this update
--    only; it would otherwise unpublish every lesson until re-approval.
alter table public.lessons disable trigger lesson_content_change_requires_review_trg;
update public.lessons set title = 'Say hello', learning_plan = learning_plan || jsonb_build_object('problem', 'Your school wants the computer in the lab to greet every visitor. How can you make a computer say hello?'::text, 'ideas', '[{"title":"A program is a list of instructions","body":"A computer does nothing on its own. It follows the instructions you give it, one by one."},{"title":"The print block shows words","body":"Put words inside a print block. When you press Run, the computer shows those words on the screen."}]'::jsonb) || '{"steps":["Find the print block.","Change its words to: Hello, learner!","Press Run. Look at the screen.","Put your own name in. Press Run again."],"expectedResult":"Hello, learner!"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000001';
update public.lessons set title = 'Steps in order', learning_plan = learning_plan || jsonb_build_object('problem', 'A small child is learning to wash their hands. The steps must come in the right order. How do you tell a computer the order?'::text, 'ideas', '[{"title":"Order matters","body":"The computer runs blocks from top to bottom. The first block runs first."},{"title":"One step, one block","body":"Put each instruction in its own print block. Snap the blocks together in the order you want."}]'::jsonb) || '{"steps":["Pick a job you do every day, like washing your hands.","Use 3 print blocks. Put one step in each.","Snap them together in the right order.","Press Run. Are the steps in order?"],"expectedResult":"Your 3 steps, one on each line, in order."}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000002';
update public.lessons set title = 'Add two numbers', learning_plan = learning_plan || jsonb_build_object('problem', 'A shopkeeper sells 7 mandazi in the morning and 5 in the afternoon. How many is that in total? Can the computer work it out for you?'::text, 'ideas', '[{"title":"Computers are good at maths","body":"A maths block takes two numbers and adds, subtracts, multiplies or divides them."},{"title":"Print the answer","body":"Put the maths block inside a print block. The computer works out the sum and shows the answer."}]'::jsonb) || '{"steps":["Take a maths block from Numbers.","Put in 7 and 5. Keep the + sign.","Put the maths block inside the print block. Press Run.","Change + to −. Press Run again."],"expectedResult":"12\nthen 2"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000003';
update public.lessons set title = 'Find the area', learning_plan = learning_plan || jsonb_build_object('problem', 'The school garden bed is 6 metres long and 4 metres wide. How much space is there to plant in?'::text, 'ideas', '[{"title":"A formula is a rule","body":"Area = length × width. A formula tells you how to work something out every time."},{"title":"Inputs change, the rule stays","body":"Put new numbers into the same multiply block and you get the area of a different garden."}]'::jsonb) || '{"steps":["Take a maths block. Choose ×.","Put in 6 and 4.","Put it inside the print block. Press Run.","Now try 3 and 5."],"expectedResult":"24\nthen 15"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000004';
update public.lessons set title = 'Bigger or smaller?', learning_plan = learning_plan || jsonb_build_object('problem', 'Two teams score in a football match. Did team A score more than team B? The computer can answer yes-or-no questions like this.'::text, 'ideas', '[{"title":"Compare two numbers","body":"A compare block asks a question such as \"is 8 greater than 3?\""},{"title":"True or false","body":"The answer to a compare block is always true or false."}]'::jsonb) || '{"steps":["Take a compare block from Choices.","Make it ask: is 8 bigger than 3?","Put it inside the print block. Press Run.","Now try: is 2 bigger than 3?"],"expectedResult":"true\nthen false"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000005';
update public.lessons set title = 'Say it again and again', learning_plan = learning_plan || jsonb_build_object('problem', 'The coach wants the screen to say "Go!" four times before the race. Do you need four print blocks, or is there a quicker way?'::text, 'ideas', '[{"title":"Repeat saves work","body":"A repeat block runs the blocks inside it again and again."},{"title":"Choose how many times","body":"The number on the repeat block says how many times to run."}]'::jsonb) || '{"steps":["Take a repeat block from Repeat.","Put a print block inside. Make it say Go!","Set the repeat to 4. Press Run.","Count the lines. Are there 4?"],"expectedResult":"Go!\nGo!\nGo!\nGo!"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000006';
update public.lessons set title = 'Remember a name', learning_plan = learning_plan || jsonb_build_object('problem', 'Your program greets a learner called Amani. Tomorrow it must greet Baraka. Can you change the name in one place only?'::text, 'ideas', '[{"title":"A variable is a labelled box","body":"A variable keeps a value, like a name or a number, under a label you choose."},{"title":"Change it once, use it everywhere","body":"When you change what is in the box, every block that uses the box gets the new value."}]'::jsonb) || '{"steps":["Open Remember. Make a box called name.","Set name to Amani.","Print name. Press Run.","Change Amani to your own name. Press Run again."],"expectedResult":"Amani\nthen your own name"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000007';
update public.lessons set title = 'Fix the order', learning_plan = learning_plan || jsonb_build_object('problem', 'A robot was told: Finish, Start, Build. It got confused. Can you find what went wrong and fix it?'::text, 'ideas', '[{"title":"A bug is a mistake","body":"When a program does something you did not expect, it has a bug."},{"title":"Compare, fix, test again","body":"Compare what you wanted with what happened. Fix one thing, then run again to check."}]'::jsonb) || '{"steps":["Make 3 print blocks: Finish, Start, Build.","Press Run. Is the order right?","Move the blocks to: Start, Build, Finish.","Press Run again to check."],"expectedResult":"Start\nBuild\nFinish"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000008';
update public.lessons set title = 'Count to 5', learning_plan = learning_plan || jsonb_build_object('problem', 'A teacher counts learners getting onto the bus: 1, 2, 3, 4, 5. How can the computer count like this by itself?'::text, 'ideas', '[{"title":"A counter is a variable that changes","body":"Start the counter at 1. Each time round the loop, add 1 to it."},{"title":"Order inside the loop matters","body":"Print first, then add 1, and the count starts at 1. Swap them and it starts at 2."}]'::jsonb) || '{"steps":["Make a box called counter. Set it to 1.","Take a repeat block. Set it to 5.","Inside: print counter, then add 1 to counter.","Press Run."],"expectedResult":"1\n2\n3\n4\n5"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000009';
update public.lessons set title = 'Times tables', learning_plan = learning_plan || jsonb_build_object('problem', 'You need to learn the 3 times table for a test. Can the computer write it out for you: 3, 6, 9, 12, 15?'::text, 'ideas', '[{"title":"Count with a loop","body":"A \"count with i from 1 to 5\" loop gives i the values 1, 2, 3, 4 and 5, one at a time."},{"title":"Use the count in maths","body":"Multiply i by 3 inside the loop. Each time round you get the next answer."}]'::jsonb) || '{"steps":["Take a count block from Repeat. Count i from 1 to 5.","Inside, print i × 3.","Press Run.","Change 3 to 4. Press Run again."],"expectedResult":"3, 6, 9, 12, 15\nthen 4, 8, 12, 16, 20"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000010';
update public.lessons set title = 'Pass or practise?', learning_plan = learning_plan || jsonb_build_object('problem', 'In a class game, 50 or more wins. Less than 50 means practise more. How can the computer choose what to say?'::text, 'ideas', '[{"title":"If … else makes a choice","body":"If a test is true, the computer runs the first set of blocks. Otherwise (else) it runs the second set."},{"title":"Check the edge","body":"Always test the number right on the line, like exactly 50."}]'::jsonb) || '{"steps":["Make a box called score. Set it to 70.","Take an if block. Use its settings to add else.","If score ≥ 50, print Target reached. Else, print Keep practising.","Try score 70, then 30, then 50."],"expectedResult":"70 → Target reached\n30 → Keep practising\n50 → Target reached"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000011';
update public.lessons set title = 'This AND that', learning_plan = learning_plan || jsonb_build_object('problem', 'A robot can only start when it has its kit AND it is ready. What if only one of those is true?'::text, 'ideas', '[{"title":"AND needs both","body":"AND is true only when both parts are true."},{"title":"OR needs one","body":"OR is true when at least one part is true."}]'::jsonb) || '{"steps":["Make two boxes: hasKit and isReady. Set both to true.","If hasKit and isReady, print Start. Else, print Not yet.","Press Run. Set one box to false. Press Run again.","Change and to or. What changes?"],"expectedResult":"Both true → Start\nOne false → Not yet"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000012';
update public.lessons set title = 'Add it all up', learning_plan = learning_plan || jsonb_build_object('problem', 'A learner saves 1 shilling on day 1, 2 on day 2, and so on up to day 5. How much is saved in total?'::text, 'ideas', '[{"title":"A running total grows","body":"Start total at 0. Each time round the loop, add the new amount to it."},{"title":"Start outside the loop","body":"Set total to 0 before the loop. If you set it inside, it goes back to 0 every time."}]'::jsonb) || '{"steps":["Make a box called total. Set it to 0.","Count i from 1 to 5. Inside, add i to total.","After the count, print total. Press Run.","Now count to 10. Press Run again."],"expectedResult":"15\nthen 55"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000013';
update public.lessons set title = 'Make a list', learning_plan = learning_plan || jsonb_build_object('problem', 'A weather station takes three temperature readings: 12, 18 and 24. How can you keep them all together and pick out one?'::text, 'ideas', '[{"title":"A list holds many values","body":"A list keeps several values in order, under one name."},{"title":"Items have places","body":"Each value has a place in the list: first, second, third. You can ask for one by its place."}]'::jsonb) || '{"steps":["Make a box called readings.","Set it to a list: 12, 18, 24.","Print how long the list is. Then print item 2.","Add a 4th number. Press Run again."],"expectedResult":"3 and 18\nthen 4"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000014';
update public.lessons set title = 'Know when to stop', learning_plan = learning_plan || jsonb_build_object('problem', 'A loop that never ends can freeze a program. How do you make sure a loop knows when to stop?'::text, 'ideas', '[{"title":"While keeps going while a test is true","body":"A \"repeat while\" loop checks its test each time. When the test becomes false, it stops."},{"title":"Something must change","body":"Inside the loop, change the variable so the test becomes false one day."}]'::jsonb) || '{"steps":["Make a box called count. Set it to 0.","Take a \"repeat while\" block: while count < 3.","Inside: print count, then add 1 to count.","Press Run. Does it stop?"],"expectedResult":"0\n1\n2"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000015';
update public.lessons set title = 'Make your own block', learning_plan = learning_plan || jsonb_build_object('problem', 'Every project follows Plan, Build, Test. You need these steps many times. Can you make your own block that prints all three?'::text, 'ideas', '[{"title":"A function is your own block","body":"Give a group of blocks a name. Then use that name whenever you need the group."},{"title":"Change once, change everywhere","body":"If you change the function, every place that uses it changes too."}]'::jsonb) || '{"steps":["Open My own blocks. Make a block called showSteps.","Inside it, print Plan, Build and Test.","Use showSteps 2 times. Press Run.","Change Test to Check. Press Run again."],"expectedResult":"Plan, Build, Test\ntwo times"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000016';
update public.lessons set title = 'A block that doubles', learning_plan = learning_plan || jsonb_build_object('problem', 'A market seller often needs to double a number. Can you make one block that doubles any number?'::text, 'ideas', '[{"title":"An input goes in","body":"A function can take an input, like n. You give it a different n each time."},{"title":"A result comes back","body":"The function returns its answer, so you can print it or use it."}]'::jsonb) || '{"steps":["Make a block called double with an input n.","Make it give back n × 2.","Print double of 3, then 0, then −2.","Press Run."],"expectedResult":"6\n0\n-4"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000017';
update public.lessons set title = 'Positive, zero or negative', learning_plan = learning_plan || jsonb_build_object('problem', 'A thermometer can read below zero, zero, or above zero. How can a program sort every number into Positive, Zero or Negative?'::text, 'ideas', '[{"title":"More than two choices","body":"Use if, else if and else to choose between three or more answers."},{"title":"Only one branch runs","body":"The computer checks each test in order and runs the first one that is true."}]'::jsonb) || '{"steps":["Make a block called sortNumber with an input n.","If n > 0, give back Positive. Else if n = 0, give back Zero. Else, give back Negative.","Print sortNumber of −5, then 0, then 5.","Press Run."],"expectedResult":"Negative\nZero\nPositive"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000018';
update public.lessons set title = 'Robot: stop or go?', learning_plan = learning_plan || jsonb_build_object('problem', 'A robot car must stop before it hits a wall. If the wall is closer than 10 centimetres, it should stop. How does it decide?'::text, 'ideas', '[{"title":"Sensors give readings","body":"A distance sensor gives a number. Here we pretend the number comes from a sensor."},{"title":"Check bad readings too","body":"Real sensors can give wrong numbers, like a negative distance. Your program should say \"Invalid reading\"."}]'::jsonb) || '{"steps":["Make a box called distance. Set it to 5.","If distance < 10, print Stop. Else, print Move.","Try 5, then 10, then 20.","Add: if distance < 0, print Invalid reading."],"expectedResult":"5 → Stop\n10 → Move\n20 → Move\n-1 → Invalid reading"}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000019';
update public.lessons set title = 'Your own program', learning_plan = learning_plan || jsonb_build_object('problem', 'Pick a real problem at school, like counting supplies or warning when something is wrong. Can you plan, build and test your own program to solve it?'::text, 'ideas', '[{"title":"Plan before you build","body":"Say what your program should do and how you will know it works."},{"title":"Test three ways","body":"Try a normal case, an edge case right on the line, and a strange input. Fix and test again."}]'::jsonb) || '{"steps":["Pick a problem. Say what your program should do.","Use a box, an if, a repeat and your own block.","Test it 3 ways: normal, on the edge, and strange.","Fix one mistake. Test again."],"expectedResult":"Your program does what you said it would."}'::jsonb where id = 'b10c1000-0000-4000-8000-000000000020';
update public.lessons set title = 'A morning guide', learning_plan = learning_plan || jsonb_build_object('problem', 'A new learner does not know the morning routine. Can you build a guide that greets them by name and tells them the steps?'::text, 'ideas', '[{"title":"Use what you know","body":"Use print for steps, a variable for the name, and repeat for a step that happens more than once."},{"title":"Ask someone to try it","body":"Let a friend follow your guide. If a step is unclear, improve it and test again."}]'::jsonb) || '{"steps":["Pick a daily job. Who is your guide for?","Print at least 4 steps. Use a box for the person''s name.","Use repeat for a step that happens more than once.","Ask a friend to try it. Fix one step that was not clear."],"expectedResult":"Hello, (name)!\nthen your steps in order","requirements":["4 or more steps, in order","A box with a name in it","A repeat block","One thing you fixed"]}'::jsonb where id = 'b10c2000-0000-4000-8000-000000000001';
update public.lessons set title = 'Count the kits', learning_plan = learning_plan || jsonb_build_object('problem', '11 learners share kits in pairs. You have 5 kits. Is that enough? Build a program that tells you.'::text, 'ideas', '[{"title":"Round up for people","body":"11 learners in pairs need 6 kits, not 5½. When sharing between people, always round up."},{"title":"Check the inputs","body":"A negative number of learners, or 0 learners per kit, makes no sense. Print \"Invalid input\" for these."}]'::jsonb) || '{"steps":["Make 3 boxes: learners, kits and learnersPerKit.","Work out how many kits you need. Round up.","If you have enough, print Enough kits. If not, print Shortage.","Test 10 learners, then 11, then 0 per kit."],"expectedResult":"10 learners → 5 kits\n11 learners → 6 kits\n0 per kit → Invalid input","requirements":["3 boxes for your numbers","Rounds up: 11 learners in pairs need 6 kits","Says Enough kits or Shortage","Says Invalid input for impossible numbers"]}'::jsonb where id = 'b10c2000-0000-4000-8000-000000000002';
update public.lessons set title = 'Robot controller', learning_plan = learning_plan || jsonb_build_object('problem', 'A robot gets four distance readings. For each one, should it Stop or Move? Build a program that decides.'::text, 'ideas', '[{"title":"One function, many readings","body":"Write one function that decides for a single reading. Then loop through the list and call it for each one."},{"title":"Name your threshold","body":"Keep the number 10 in a variable. Then it is easy to change later."}]'::jsonb) || '{"steps":["Make your own block that takes a distance.","It gives back Stop below 10, Move at 10 or more, and Invalid reading if below 0.","Put −1, 5, 10 and 20 in a list. Repeat for each one.","Press Run. Check each answer."],"expectedResult":"Invalid reading\nStop\nMove\nMove","requirements":["Your own block with a distance input","Stop, Move and Invalid reading","A list and a repeat","A test at exactly 10"]}'::jsonb where id = 'b10c2000-0000-4000-8000-000000000003';
alter table public.lessons enable trigger lesson_content_change_requires_review_trg;

-- 4. Before / during / end checks for every lesson. The end check repeats the
